#!/usr/bin/env bash
#
# goaiez-runtime.sh — THE ENTIRE RUNTIME IN ONE FILE.
#
# ⭐⭐⭐ WHY THIS EXISTS:
#
# The chat interface shows about ten files at a time, so downloading 117 of them
# one screen at a time does not work — the first attempt landed 7 files out of
# 117 and every artisan command was missing. That was not a user error; it was a
# delivery problem, and this file is the fix.
#
# Everything the runtime needs is embedded below as a base64 tarball: 30 php
# files, the installer, .env.ci, ci.yml, Procfile, deploy/.
#
#   Usage:
#     bash goaiez-runtime.sh /path/to/laravel/tree
#
# ⛔ The 76 GOAIEZ-*.md package files are 4.3 MB and are NOT in here. Download
#    those separately into the Laravel root — five classes read them, and
#    without them the scaffold reports "0 modules" instead of failing.
#
set -euo pipefail
ok()   { printf '  \033[32m✓\033[0m %s\n' "$*"; }
warn() { printf '  \033[33m!\033[0m %s\n' "$*"; }
die()  { printf '\n  \033[31m✗ %s\033[0m\n\n' "$*"; exit 1; }

DEST="${1:-}"
[ -n "$DEST" ] || die "Usage: bash goaiez-runtime.sh /path/to/laravel/tree"
[ -d "$DEST" ] || die "Not a directory: $DEST"
[ -f "$DEST/artisan" ] || die "No 'artisan' in $DEST — that is not a Laravel root."

BUILD="20260829-0647"
printf '\n\033[1mGOAIEZ runtime — build %s\033[0m\n' "$BUILD"

# ⭐⭐⭐ SHOW THE SWAP. Three consecutive doctor runs produced byte-identical
#    output because the files were re-downloaded into a download folder and
#    never copied into the tree. Nothing in any output said so.
PREV=$(grep -o "const BUILD = '[0-9-]*'" "$DEST/app/Console/Commands/DoctorCommand.php" 2>/dev/null | grep -oE '[0-9]{8}-[0-9]{4}' || true)

[ -n "$PREV" ] || PREV="none"
if [ "$PREV" = "$BUILD" ]; then
  warn "the tree ALREADY has build $BUILD — nothing will change"
elif [ "$PREV" = "none" ]; then
  ok "no previous build in the tree — first install"
else
  ok "replacing build $PREV  ->  $BUILD"
fi
printf '  into: %s\n' "$DEST"

TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT

# ⭐ The payload is at the end of this file, after the __PAYLOAD__ marker.
sed -n '/^__PAYLOAD__$/,$p' "$0" | tail -n +2 | base64 -d | tar xzf - -C "$TMP"

FOUND=$(find "$TMP" -type f | wc -l | tr -d ' ')
ok "unpacked $FOUND files"

# ⛔ Copy, warning on any DIFFERING overwrite. A collision means the live tree
#    and this package disagree about who owns that path — a finding, not noise.
while IFS= read -r f; do
  rel="${f#$TMP/}"
  mkdir -p "$DEST/$(dirname "$rel")"
  if [ -f "$DEST/$rel" ] && ! cmp -s "$f" "$DEST/$rel"; then
    warn "OVERWRITING (differs): $rel"
  fi
  cp "$f" "$DEST/$rel"
done < <(find "$TMP" -type f)

# ── verify — count what actually landed ───────────────────────────────
# ⭐⭐⭐ RE-SEAL. The seals ship in the payload, so they are already correct —
#    this only re-computes if a local edit was DELIBERATE and the operator wants
#    it blessed. It is intentionally NOT automatic: an install must not quietly
#    launder someone's edit into the baseline.
if [ "${GOAIEZ_RESEAL:-}" = "1" ]; then
  php -r '
    $s=[];
    foreach (array_merge(glob("app/Doctor/Stages/*.php"), glob("app/Doctor/*.php")) as $f) {
      if (str_ends_with($f,"IntegrityStage.php")) continue;
      $s[$f]=hash("sha256",file_get_contents($f));
    }
    ksort($s);
    file_put_contents("app/Doctor/seals.json", json_encode($s, JSON_PRETTY_PRINT));
  ' 2>/dev/null && warn "RE-SEALED on request (GOAIEZ_RESEAL=1) — local edits are now the baseline"
fi

# ⭐⭐⭐ THE SEAL DIGEST. WRITE IT DOWN.
#
# `php artisan doctor:selftest` prints this same digest. If they ever differ,
# seals.json was edited after install — which is exactly what happened once,
# when an agent recomputed the hashes to make a mismatch go away.
#
# ⛔ The anchor cannot live on the machine the agent controls. It lives here,
#   in your notes.
printf '\n  \033[1mSEAL DIGEST\033[0m  f1e73d9fc181eb1c\n'
printf '  \033[33mWrite this down. doctor:selftest must print the same 16 characters.\033[0m\n'

printf '\n\033[1mVerify\033[0m\n'
# ⛔⛔ `set -e` + a failing glob kills the script SILENTLY — the first version
#    of this block printed nothing at all and exited 0, which is the worst
#    possible outcome: it looks like success. Every count is now guarded.
# ⛔⛔ COUNT MY 13 BY NAME — NOT THE DIRECTORY.
#
# The first version counted every .php in app/Console/Commands and found 77 on
# a real tree, because the tree has 64 commands of its own. It then DIED on
# "expected 13, found 77" — after the copy had already happened, so the install
# both worked and reported failure.
#
# ⭐ A verify that cannot tell my files from the project's files is not a
#   verify. These are the thirteen this bundle ships.
MINE="BriefCommand CapabilitiesScaffoldCommand ContextCommand DbBootstrapCommand DeployCheckCommand DoctorCommand FindCommand ImpactCommand DoctorSelfTestCommand MakeModuleCommand MapCommand ModuleDoneCommand ModuleScaffoldCommand WhyCommand"
C=0
for n in $MINE; do
  [ -f "$DEST/app/Console/Commands/$n.php" ] && C=$((C+1))
done
S=$(find "$DEST/app/Doctor/Stages" -name '*.php' 2>/dev/null | wc -l | tr -d ' ' || echo 0)
D=$(find "$DEST/app/Doctor" -maxdepth 1 -name '*.php' 2>/dev/null | wc -l | tr -d ' ' || echo 0)
V=0; [ -f "$DEST/app/Providers/GoaiezRuntimeServiceProvider.php" ] && V=1
T=0
for n in "Journeys/JourneyHarness" "Journeys/TwelveJourneysTest" "Patches/FourPatchesTest" "Runtime/RuntimeProofTest"; do
  [ -f "$DEST/tests/$n.php" ] && T=$((T+1))
done
P=$(find "$DEST" -maxdepth 1 -name 'GOAIEZ-*.md' 2>/dev/null | wc -l | tr -d ' ' || echo 0)
printf '  commands           %3s  (expect 14)\n' "$C"
printf '  doctor stages      %3s  (expect 8)\n' "$S"
printf '  doctor core        %3s  (expect 4)\n' "$D"
printf '  service provider   %3s  (expect 1)\n' "$V"
printf '  test files         %3s  (expect 4)\n' "$T"
printf '  package .md        %3s  (expect 76 — download separately)\n' "$P"

[ "$C" -eq 14 ] || die "Expected 14 commands, found $C."
[ "$V" -eq 1 ]  || die "Service provider missing — NOTHING would register."
ok "runtime complete"

if [ "$P" -lt 70 ]; then
  printf '\n'
  warn "Only $P GOAIEZ-*.md in the root."
  warn "FIVE classes read them from base_path(): module:scaffold,"
  warn "capabilities:scaffold, find, why, CitationStage. Without them the"
  warn "scaffold reports '0 modules' as though the system were EMPTY."
  warn "Download them into $DEST, THEN run install-step-0.sh."
fi

cat <<'NEXT'

────────────────────────────────────────────────────────────────
  ✓ Runtime unpacked. Next:

      cd <your laravel tree>
      bash install-step-0.sh

  ⛔ Expect doctor to report violations. That is the system
     working. A first run reporting ZERO would mean the checks
     are not connected to anything.
────────────────────────────────────────────────────────────────
NEXT
exit 0

__PAYLOAD__

